// Generates extension/pcms/sandbox/controller.js, the classic-script entry of the
// controller sandbox page. A declared sandbox page has an opaque origin, and Firefox
// fetches module scripts in CORS mode, so the shipped page cannot load ES modules from
// the extension (P030 CI observation; the P027 classic-script fixture runs). protocol.js
// and controller-runtime.js stay the single source of truth; this file only inlines them.
//
//   node tests/pcms/p030/controller-bundle.mjs --write   regenerate
//   node tests/pcms/p030/controller-bundle.mjs           exit 1 when out of date
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

export const CONTROLLER_BUNDLE_PATH = "extension/pcms/sandbox/controller.js";

function stripExports(source, file) {
  const names = [];
  const out = source.replace(/^export (const|function|class) ([A-Za-z_$][\w$]*)/gm, (_, kind, name) => {
    names.push(name);
    return kind + " " + name;
  });
  if (/^\s*export\b/m.test(out)) throw new Error("Unsupported export form in " + file);
  return { code: out, names };
}

export async function buildControllerBundle() {
  const protocolSource = await readFile("extension/pcms/sandbox/protocol.js", "utf8");
  const runtimeSource = await readFile("extension/pcms/sandbox/controller-runtime.js", "utf8");
  if (/^\s*import\b/m.test(protocolSource)) throw new Error("protocol.js must stay import-free");
  const protocol = stripExports(protocolSource, "protocol.js");

  const importPattern = /^import \{([^}]*)\} from "\.\/protocol\.js";\n/m;
  const match = importPattern.exec(runtimeSource);
  if (!match) throw new Error("controller-runtime.js must import only from ./protocol.js");
  const imported = match[1].split(",").map((name) => name.trim()).filter(Boolean);
  for (const name of imported) {
    if (!protocol.names.includes(name)) throw new Error("protocol.js does not export " + name);
  }
  const runtimeBody = runtimeSource.replace(importPattern,
    "const { " + imported.join(", ") + " } = pcmsSandboxProtocol;\n");
  if (/^\s*import\b/m.test(runtimeBody)) throw new Error("controller-runtime.js has more than one import");
  const runtime = stripExports(runtimeBody, "controller-runtime.js");

  return [
    "// GENERATED by tests/pcms/p030/controller-bundle.mjs from protocol.js and",
    "// controller-runtime.js. Do not edit; run the generator with --write instead.",
    "// Classic script: the opaque-origin sandbox page cannot fetch ES modules (P030).",
    "(() => {",
    "\"use strict\";",
    "const pcmsSandboxProtocol = (() => {",
    protocol.code.trimEnd(),
    "return Object.freeze({ " + protocol.names.join(", ") + " });",
    "})();",
    "const pcmsSandboxControllerRuntime = (() => {",
    runtime.code.trimEnd(),
    "return Object.freeze({ " + runtime.names.join(", ") + " });",
    "})();",
    "pcmsSandboxControllerRuntime.installSandboxControllerRuntime();",
    "})();",
    ""
  ].join("\n");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const bundle = await buildControllerBundle();
  if (process.argv.includes("--write")) {
    await writeFile(CONTROLLER_BUNDLE_PATH, bundle);
    console.log("Wrote " + CONTROLLER_BUNDLE_PATH);
  } else {
    const current = await readFile(CONTROLLER_BUNDLE_PATH, "utf8");
    if (current !== bundle) {
      console.error(CONTROLLER_BUNDLE_PATH + " is out of date; run with --write");
      process.exit(1);
    }
    console.log(CONTROLLER_BUNDLE_PATH + " is current");
  }
}
